// src/app/cli.ts
async function runCli() {
  const command = new import_commander.Command().name("diy-cli").description("Analyze DIY capability usage").option("--graph", "Print a capability module graph").requiredOption("-p, --project <path>", "Path to the diy.json project file").allowExcessArguments(false).parse();
  const options = command.opts();
  const cwd = process.cwd();
  const project = await resolveDiyProject(options.project, cwd);
  const projectCwd = project.cwd;
  process.chdir(projectCwd);
  const analyzeOptions = { cwd: projectCwd };
  if (options.graph === true) {
    const analysis2 = await analyzeDiy(project.config, analyzeOptions);
    if (analysis2.unsupported.length > 0 || analysis2.violations.length > 0) {
      const output2 = formatDiyAnalysis(analysis2, analyzeOptions);
      if (output2.length > 0) {
        process.stderr.write(output2);
      }
      process.exitCode = 1;
    } else {
      const graph = await analyzeDiyModuleGraph(project.config, analyzeOptions);
      process.stdout.write(formatDiyModuleGraph(graph, analyzeOptions));
    }
    return;
  }
  const analysis = await analyzeDiy(project.config, analyzeOptions);
  const output = formatDiyAnalysis(analysis, analyzeOptions);
  if (output.length > 0) {
    process.stderr.write(output);
  }
  if (analysis.unsupported.length > 0 || analysis.violations.length > 0 || analysis.findings.length > 0) {
    process.exitCode = 1;
  } else {
    process.stdout.write(`DIY analyzer passed: ${analysis.coveredFiles.length} files analyzed.
`);
  }
}
